import { ChangeDetectionStrategy, Component, input } from '@angular/core';

@Component({
  selector: 'aevko-bubble',
  standalone: true,
  template:
    '<div class="content"><ng-content /></div><div class="reactions"><ng-content select="[aevkoBubbleReactions]" /></div>',
  styleUrl: './bubble.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { '[attr.data-align]': 'align()', '[attr.data-variant]': 'variant()' },
})
export class AevkoBubble {
  readonly align = input<'start' | 'end'>('start');
  readonly variant = input<'default' | 'muted' | 'outline'>('default');
}

:host {
  background: var(--aevko-foreground, #09090b);
  color: var(--aevko-background, #fff);
  display: block;
  inline-size: fit-content;
  max-inline-size: min(34rem, 85%);
  padding: 0.75rem 1rem;
}
:host([data-align='end']) {
  margin-inline-start: auto;
}
:host([data-variant='muted']) {
  background: var(--aevko-surface, #f4f4f5);
  color: var(--aevko-foreground, #09090b);
}
:host([data-variant='outline']) {
  background: transparent;
  border: 1px solid var(--aevko-border, #e4e4e7);
  color: var(--aevko-foreground, #09090b);
}
.reactions {
  margin-top: 0.5rem;
}
.reactions:empty {
  display: none;
}
